  box-shadow: 0 6px 20px rgba(0,0,0,0.2);
}

.music-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.7);
  transition: filter 0.3s ease;
}

.music-avatar:hover .music-avatar-img {
  filter: brightness(1);
}

/* 播放按钮覆盖层 */
.play-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
