  color: white;
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(102, 126, 234, 0.4);
}

.control-btn.main {
  width: 36px;
  height: 36px;
  font-size: 14px;
  background: linear-gradient(135deg, #667eea, #764ba2);
